function attributesForTag(template, tag) {
  const match = template.match(new RegExp(`<${tag}\\s+([\\s\\S]*?)>`));
  assert(match, `${tag} mount is required`);
  const attributes = {};
  const pattern = /([\w-]+)\s*=\s*"([^"]*)"/g;
  let attribute;
  while ((attribute = pattern.exec(match[1])) !== null) {
